;---------------------------------------------------------
; sakura — рисует картинку
;   IN:  eax = x, ebx = y
;   CLOBBER: всё (pushad/popad сохраняет)
;---------------------------------------------------------
sakura:
    pushad
    mov  esi, sakura_palette

; --- копировать палитру в palette16/palette256 ---
    mov  edi, palette_buf
    mov  ecx, 16
    rep  movsd

; --- вычислить адрес в framebuffer ---
    imul ebx, [pitch]
    shl  eax, 2
    add  ebx, eax
    mov  edi, [framebuffer]
    add  edi, ebx

; --- цикл ---
    mov  edx, sakura_h
    mov  ebp, sakura_w
    add  ebp, 1
    shr  ebp, 1
.row:
    test edx, edx
    jz   .done
    push edi
    push esi
    push ebp
    mov  ecx, sakura_w
.pair:
    test ecx, ecx
    jz   .row_done
    movzx eax, byte [esi]
    inc  esi
    mov  ebx, eax
    shr  ebx, 4
    mov  ebx, [palette_buf + ebx*4]
    mov  [edi], ebx
    add  edi, 4
    dec  ecx
    jz   .pair_done
    and  eax, 0x0F
    mov  eax, [palette_buf + eax*4]
    mov  [edi], eax
    add  edi, 4
    dec  ecx
    jmp  .pair
.pair_done:
.row_done:
    pop  ebp
    pop  esi
    pop  edi
    add  esi, ebp
    mov  eax, [pitch]
    add  edi, eax
    dec  edx
    jmp  .row
.done:
    popad
    ret


;---------------------------------------------------------
; Общий буфер палитры (16 dword)
;---------------------------------------------------------
palette_buf:
    times 16 dd 0
